  @Nested
  @DisplayName("Queries")
  class Queries {

    @Test
    @DisplayName("Should load children in batches and complete each parent future")
    void shouldLoadChildren() {
      // Arrange — three users and their roles, loaded two parents at a time
      rows.put("FROM users", List.of(row("id", "u1"), row("id", "u2"), row("id", "u3")));
      rows.put("user_id IN (?, ?)", List.of(row("user_id", "u1", "name", "admin"),
          row("user_id", "u1", "name", null), row("user_id", "u2", "name", "viewer")));
      Map<String, CompletionStage<List<String>>> roles = new HashMap<>();
      SqlQuery<String> query = traced().createSqlQuery("SELECT * FROM users");
      query.child(2, "roles", "SELECT * FROM roles WHERE user_id IN (:user_id)", "id", "user_id",
          rs -> Optional.ofNullable(rs.getString("name")));

      // Act — run the query under a traced parent span
      List<String> ids;
      try (Scope ignored = validParent().makeCurrent()) {
        ids = query.query(rs -> {
          roles.put(rs.getString("id"), rs.getChilds("roles"));
          return Optional.of(rs.getString("id"));
        }).all();
      }

      // Assert — every parent gets its own children
      assertEquals(List.of("u1", "u2", "u3"), ids);
      assertEquals(List.of("admin"), roles.get("u1").toCompletableFuture().join());
      assertEquals(List.of("viewer"), roles.get("u2").toCompletableFuture().join());
      assertEquals(List.of(), roles.get("u3").toCompletableFuture().join());
      assertTrue(prepared.contains("SELECT * FROM roles WHERE user_id IN (?, ?)"));
      assertTrue(prepared.contains("SELECT * FROM roles WHERE user_id IN (?)"));
    }

    @Test
    @DisplayName("Should limit the results keeping the lock clause at the end")
    void shouldLimitResults() {
      rows.put("FROM users", List.of(row("id", "u1")));
      SqlTemplate template = new SqlTemplate(connection);

      assertEquals(Optional.of("u1"),
          template.<String>createSqlQuery("SELECT * FROM users").forUpdate().query(ID).one());
      assertEquals("SELECT * FROM users  limit 1 FOR UPDATE", last());
      template.<String>createSqlQuery("SELECT * FROM users").query(ID).limit(Optional.of(5));
      assertEquals("SELECT * FROM users limit 5", last());
      template.<String>createSqlQuery("SELECT * FROM users").query(ID).limit(Optional.empty());
      assertEquals("SELECT * FROM users", last());
    }

    @Test
    @DisplayName("Should translate SQL errors of the main query")
    void shouldTranslateQueryErrors() {
      failOn = sql -> sql.contains("FROM users") ? new SQLException("boom", "42000", 1) : null;
      try (Scope ignored = validParent().makeCurrent()) {
        assertThrows(UncheckedSqlException.class,
            () -> traced().<String>createSqlQuery("SELECT * FROM users").query(ID).all());
      }
    }

    @Test
    @DisplayName("Should rethrow runtime errors of the main query")
    void shouldRethrowQueryRuntimeErrors() {
      try (Scope ignored = validParent().makeCurrent()) {
        assertThrows(IllegalArgumentException.class,
            () -> traced().<String>createSqlQuery("SELECT * FROM users")
                .with("x", SqlParameterValue.of(1)).query(ID).all());
      }
    }

    @Test
    @DisplayName("Should translate SQL errors of a child query")
    void shouldTranslateChildErrors() {
      rows.put("FROM users", List.of(row("id", "u1")));
      failOn = sql -> sql.contains("FROM roles") ? new SQLException("boom", "42000", 1) : null;
      SqlQuery<String> query = traced().createSqlQuery("SELECT * FROM users");
      query.child(10, "roles", "SELECT * FROM roles WHERE user_id IN (:user_id)", "id", "user_id",
          ID);

      try (Scope ignored = validParent().makeCurrent()) {
        assertThrows(UncheckedSqlException.class, () -> query.query(ID).all());
      }
    }

    @Test
    @DisplayName("Should rethrow runtime errors of a child converter")
    void shouldRethrowChildRuntimeErrors() {
      rows.put("FROM users", List.of(row("id", "u1")));
      rows.put("FROM roles", List.of(row("user_id", "u1")));
      SqlQuery<String> query = traced().createSqlQuery("SELECT * FROM users");
      query.child(10, "roles", "SELECT * FROM roles WHERE user_id IN (:user_id)", "id", "user_id",
          _ -> {
            throw new IllegalStateException("bad row");
          });

      try (Scope ignored = validParent().makeCurrent()) {
        assertThrows(IllegalStateException.class, () -> query.query(ID).all());
      }
    }
  }

  @Nested
  @DisplayName("Schematic queries")
  class Schematic {

    @Test
    @DisplayName("Should build a select with fields, joins, filters and order")
    void shouldBuildSelect() {
      SqlSchematicQuery<String> query =
          new SqlTemplate(connection).createSqlSchematicQuery("users");

      query.select("count(*)").addSelection("max(age)").selectFields("u.id")
          .addSelectedFields("u.name").join("roles", "r", "u.role", "r.id")
          .where("u", "name", SqlOperator.EQ, SqlParameterValue.of("ana"))
          .where("age", SqlOperator.GT, SqlParameterValue.of(18))
          .where("u", "deleted", SqlOperator.IS_NULL, null)
          .where(null, "deleted", SqlOperator.IS_NULL, null)
          .where("u", "mail", SqlOperator.IS_NOT_NULL, null)
          .where(null, "mail", SqlOperator.IS_NOT_NULL, null)
          .where(PartialWhere.or(PartialWhere.where("r", "kind", SqlOperator.IS_NULL, null),
              PartialWhere.where("kind", SqlOperator.EQ, SqlParameterValue.of("x")),
              PartialWhere.where("r", "alias", SqlOperator.IS_NOT_NULL, null)))
          .where(PartialWhere.empty()).orderAsc("name").addOrderDesc("age").orderDesc("id")
          .addOrderAsc("name").forUpdate().forQuery();
      query.child(5, "roles", "SELECT * FROM roles WHERE user_id IN (:user_id)", "id", "user_id",
          ID);
      query.query(ID).all();

      String sql = prepared.get(0);
      assertTrue(sql.startsWith("SELECT `u`.`id`, `u`.`name` FROM `users`  JOIN `roles` as `r`"),
          sql);
      assertTrue(sql.contains("`u`.`deleted` is null"), sql);
      assertTrue(sql.contains("`mail` is not null"), sql);
      assertTrue(sql.contains("`r`.`kind` IS NULL"), sql);
      assertTrue(sql.endsWith("ORDER BY `id` desc, `name` asc"), sql);
    }

    @Test
    @DisplayName("Should select everything and lock the table on SQL Server")
    void shouldLockOnSqlServer() throws SQLException {
      when(meta.getDriverName()).thenReturn("Microsoft JDBC Driver for SQLServer");

      new SqlTemplate(connection).<String>createSqlSchematicQuery("users").forUpdate().query(ID)
          .all();

      assertEquals("SELECT  *  FROM `users` WITH (UPDLOCK, ROWLOCK)  ", prepared.get(0));
    }

    @Test
    @DisplayName("Should build delete, insert and update statements")
    void shouldBuildOtherStatements() {
      SqlTemplate template = new SqlTemplate(connection);
      SqlSchematicQuery<String> params = template.createSqlSchematicQuery("users");

      SchematicQuery delete = new SchematicQuery(template, "DELETE", "users", params);
      assertEquals("DELETE FROM \"users\" ", delete.buildQuery());
      delete.where("id", SqlOperator.EQ, SqlParameterValue.of("u1"));
      assertTrue(delete.buildQuery().endsWith(" WHERE \"id\" = :_field_0"), delete.buildQuery());

      SchematicQuery insert = new SchematicQuery(template, "INSERT", "users", params);
      insert.set("name", SqlParameterValue.of("ana"));
      insert.set("mail", SqlParameterValue.of("ana@example.com"));
      assertEquals("INSERT INTO \"users\" (\"name\", \"mail\") VALUES (:_value_0, :_value_1)",
          insert.buildQuery());

      SchematicQuery update = new SchematicQuery(template, "UPDATE", "users", params);
      update.set("name", SqlParameterValue.of("ana"));
      update.set("mail", SqlParameterValue.of("ana@example.com"));
      assertEquals("UPDATE \"users\" SET \"name\" = :_value_0, \"mail\" = :_value_1 ",
          update.buildQuery());
      update.where("id", SqlOperator.EQ, SqlParameterValue.of("u1"));
      assertTrue(update.buildQuery().contains(" WHERE \"id\" ="), update.buildQuery());

      SchematicQuery ordered = new SchematicQuery(template, "SELECT", "users", params);
      ordered.orderAsc("name");
      ordered.addOrderDesc("age");
      ordered.addOrderAsc("id");
      assertTrue(ordered.buildQuery().endsWith("ORDER BY \"name\" asc, \"age\" desc, \"id\" asc"),
          ordered.buildQuery());

      SchematicQuery other = new SchematicQuery(template, "MERGE", "users", params);
      assertNull(other.buildQuery());
      assertTrue(other.getParametrized() == params);
    }
  }
